def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one occurrence, found {count}")
    return text.replace(old, new, 1)


def matching_brace(text: str, opening: int) -> int:
    depth = 1
    in_string = False
    escaped = False
    for i in range(opening + 1, len(text)):
        ch = text[i]
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue
        if ch == '"':
            in_string = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return i
    raise RuntimeError("unbalanced brace")


def rule_span(text: str, prefix: str) -> tuple[int, int]:
    start = text.index(f'rule("{prefix}')
    opening = text.index("{", start)
    end = matching_brace(text, opening) + 1
    return start, end


def actions_body(rule_text: str) -> str:
    marker = "\tactions\n\t{"
    at = rule_text.index(marker)
    opening = rule_text.index("{", at)
    closing = matching_brace(rule_text, opening)
    return rule_text[opening + 1:closing]


def git_blob_sha(path: Path) -> str:
    data = path.read_bytes().replace(b"\r\n", b"\n")
    payload = b"blob " + str(len(data)).encode("ascii") + b"\0" + data
    return hashlib.sha1(payload).hexdigest()


